static bool pick(const void *tab, int rows, char c, GlyphBits *out) {
    int idx = (int)c - 32;
    if (idx < 0 || idx > 94) return false;
    if (rows == 18) {
        const GlyphRec *g = &((const GlyphRec *)tab)[idx];
        out->adv = g->adv; out->w = g->w; out->rows = 18; out->bits = g->bits;
    } else {
        const MonoRec *g = &((const MonoRec *)tab)[idx];
        out->adv = g->adv; out->w = g->w; out->rows = 16; out->bits = g->bits;
    }
    return true;
}

bool font_glyph_ui(char c, GlyphBits *out) { return pick(UI_TABLE, 18, c, out); }
bool font_glyph_mono(char c, GlyphBits *out) { return pick(MONO_TABLE, 16, c, out); }
